#include<iostream>
using namespace std;
int main() {
float a, b, c, s, area;
cout << "Enter the sides of the triangle: ";
cin >> a >> b >> c;
s = (a + b + c) / 2;
area = sqrt(s * (s - a) * (s - b) * (s - c));
cout << "The area of the triangle is: " << area;
return 0;
}

